INSERT INTO `payments` (`payment_id`, `invoice_id`, `appointment_id`, `amount_paid`, `payment_method`, `verification_status`, `payment_status`, `transaction_reference`, `payment_date`, `received_by_user_id`, `void_reason`, `corrected_at`) VALUES
