--
-- Structure for view `v_daily_sales`
--
DROP TABLE IF EXISTS `v_daily_sales`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_daily_sales`  AS SELECT cast(`payments`.`payment_date` as date) AS `sale_date`, count(0) AS `payments`, sum(`payments`.`amount_paid`) AS `total_sales` FROM `payments` WHERE `payments`.`payment_status` = 'Recorded' AND `payments`.`verification_status` = 'Verified' GROUP BY cast(`payments`.`payment_date` as date) ;

-- --------------------------------------------------------

--
-- Structure for view `v_inventory_status`
--
DROP TABLE IF EXISTS `v_inventory_status`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_inventory_status`  AS SELECT `i`.`inventory_id` AS `inventory_id`, `i`.`item_name` AS `item_name`, `i`.`category` AS `category`, `i`.`quantity` AS `quantity`, `i`.`unit_price` AS `unit_price`, `i`.`minimum_stock` AS `minimum_stock`, `i`.`expiration_date` AS `expiration_date`, `i`.`created_at` AS `created_at`, `i`.`updated_at` AS `updated_at`, CASE WHEN `i`.`expiration_date` is not null AND `i`.`expiration_date` < curdate() THEN 'Expired' WHEN `i`.`quantity` = 0 THEN 'Out of Stock' WHEN `i`.`quantity` <= `i`.`minimum_stock` THEN 'Low Stock' WHEN `i`.`expiration_date` is not null AND `i`.`expiration_date` <= curdate() + interval 30 day THEN 'Expiring Soon' ELSE 'In Stock' END AS `stock_status` FROM `inventory` AS `i` ;

-- --------------------------------------------------------

--
-- Structure for view `v_invoices`
--
DROP TABLE IF EXISTS `v_invoices`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_invoices`  AS SELECT `i`.`invoice_id` AS `invoice_id`, `i`.`invoice_no` AS `invoice_no`, `i`.`appointment_id` AS `appointment_id`, `a`.`appointment_date` AS `appointment_date`, `p`.`pet_id` AS `pet_id`, `p`.`pet_name` AS `pet_name`, `p`.`owner_id` AS `owner_id`, `o`.`full_name` AS `owner_name`, coalesce(`l`.`invoice_total`,0) AS `invoice_total`, coalesce(`pay`.`amount_paid`,0) AS `amount_paid`, greatest(coalesce(`l`.`invoice_total`,0) - coalesce(`pay`.`amount_paid`,0),0) AS `balance_due`, `i`.`invoice_status` AS `payment_status`, `i`.`generated_at` AS `generated_at` FROM (((((`invoices` `i` join `appointments` `a` on(`a`.`appointment_id` = `i`.`appointment_id`)) join `pets` `p` on(`p`.`pet_id` = `a`.`pet_id`)) join `petowners` `o` on(`o`.`owner_id` = `p`.`owner_id`)) left join (select `invoicelines`.`invoice_id` AS `invoice_id`,sum(`invoicelines`.`line_total`) AS `invoice_total` from `invoicelines` group by `invoicelines`.`invoice_id`) `l` on(`l`.`invoice_id` = `i`.`invoice_id`)) left join (select `payments`.`invoice_id` AS `invoice_id`,sum(`payments`.`amount_paid`) AS `amount_paid` from `payments` where `payments`.`payment_status` = 'Recorded' group by `payments`.`invoice_id`) `pay` on(`pay`.`invoice_id` = `i`.`invoice_id`)) ;

-- --------------------------------------------------------

--
-- Structure for view `v_unpaid_balances`
--
DROP TABLE IF EXISTS `v_unpaid_balances`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_unpaid_balances`  AS SELECT `v_invoices`.`invoice_id` AS `invoice_id`, `v_invoices`.`invoice_no` AS `invoice_no`, `v_invoices`.`appointment_id` AS `appointment_id`, `v_invoices`.`appointment_date` AS `appointment_date`, `v_invoices`.`pet_id` AS `pet_id`, `v_invoices`.`pet_name` AS `pet_name`, `v_invoices`.`owner_id` AS `owner_id`, `v_invoices`.`owner_name` AS `owner_name`, `v_invoices`.`invoice_total` AS `invoice_total`, `v_invoices`.`amount_paid` AS `amount_paid`, `v_invoices`.`balance_due` AS `balance_due`, `v_invoices`.`payment_status` AS `payment_status`, `v_invoices`.`generated_at` AS `generated_at` FROM `v_invoices` WHERE `v_invoices`.`balance_due` > 0 AND `v_invoices`.`payment_status` <> 'Void' ;

-- --------------------------------------------------------

--
-- Structure for view `v_upcoming_appointments`
--
DROP TABLE IF EXISTS `v_upcoming_appointments`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_upcoming_appointments`  AS SELECT `a`.`appointment_id` AS `appointment_id`, `a`.`appointment_date` AS `appointment_date`, `a`.`duration_minutes` AS `duration_minutes`, `a`.`status` AS `status`, `p`.`pet_name` AS `pet_name`, `o`.`full_name` AS `owner_name`, `v`.`full_name` AS `vet_name` FROM (((`appointments` `a` join `pets` `p` on(`p`.`pet_id` = `a`.`pet_id`)) join `petowners` `o` on(`o`.`owner_id` = `p`.`owner_id`)) left join `veterinarians` `v` on(`v`.`vet_id` = `a`.`vet_id`)) WHERE `a`.`status` in ('Pending','Scheduled','Waiting','Check-in','In Consultation') AND `a`.`appointment_date` >= curdate() ;

-- --------------------------------------------------------

--
-- Structure for view `v_vaccination_log`
--
DROP TABLE IF EXISTS `v_vaccination_log`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_vaccination_log`  AS SELECT `v`.`vaccination_id` AS `vaccination_id`, `v`.`pet_id` AS `pet_id`, `v`.`appointment_id` AS `appointment_id`, `v`.`administered_by_user_id` AS `administered_by_user_id`, `v`.`vaccination_name` AS `vaccination_name`, `v`.`vaccination_date` AS `vaccination_date`, `v`.`next_due_date` AS `next_due_date`, `v`.`notes` AS `notes`, `v`.`created_at` AS `created_at`, `p`.`pet_name` AS `pet_name`, `p`.`owner_id` AS `owner_id` FROM (`vaccinations` `v` join `pets` `p` on(`p`.`pet_id` = `v`.`pet_id`)) ;

